(ns pgmalli-next.impl.files-test
  "The config and the text of a generated file; no database."
  (:require [clojure.string :as str]
            [clojure.test :refer [deftest is testing]]
            [pgmalli-next.impl.files :as files]
            [pgmalli-next.impl.pattern :as p]))

(deftest generated-data-must-be-edn
  (is (thrown? clojure.lang.ExceptionInfo (files/edn-string {:registry {:x [:fn (fn [_] true)]}})))
  (let [s (files/edn-string {:registry {:pg.public/t [:map [:a ['inst? {:pg/type "timestamptz"}]]]}})]
    (is (str/starts-with? s ";; generated by pgmalli"))
    (is (not (str/includes? s "#:pg")))))

(deftest a-misspelt-config-key-names-the-key-meant
  (let [e (is (thrown-with-msg? clojure.lang.ExceptionInfo #"invalid config: .*:outt .*; did you mean: :out" (files/config {:outt "x"})))]
    (is (= :pgmalli.error/invalid-config (:pgmalli/error (ex-data e))))
    (is (= :cognitect.anomalies/incorrect (:cognitect.anomalies/category (ex-data e))))))

(deftest schemas-as-a-string-is-an-error
  (is (thrown-with-msg? clojure.lang.ExceptionInfo #"should be a vector of schema names" (files/config {:schemas "public"}))))

(deftest a-config-error-leaves-the-db-map-out
  (let [e (is (thrown? clojure.lang.ExceptionInfo (files/config {:db {:password "s3cret"} :schemas "public"})))]
    (is (not (str/includes? (pr-str (ex-data e)) "s3cret")))))

(deftest a-column-override-names-a-column-of-a-schema-generated
  (let [facts (p/facts {:name "public" :types {}
                        :tables {"jobs" {:columns [{:name "input" :position 1 :data_type "jsonb" :is_nullable false}
                                                   {:name "n" :position 2 :data_type "integer" :is_nullable false}]
                                         :constraints {}}}})
        checked #(files/checked-overrides! % facts)
        fails (fn [overrides] (try (checked overrides) nil (catch clojure.lang.ExceptionInfo e [(ex-message e) (:pgmalli/error (ex-data e)) (:did-you-mean (ex-data e))])))
        ok {:public.jobs/input [:map [:p [:ref :app/prompt]]] :public.jobs/n :pg/integer}]
    (is (= ok (checked ok)) "a reference to the user's registry")
    (testing "a type key is an error naming the columns of the type, by an alias too"
      (is (= [":overrides: :jsonb names a type: give each column a schema, :schema.table/column (:public.jobs/input)" :pgmalli.error/invalid-config nil]
             (fails {:jsonb :map})))
      (is (= [":overrides: :int4 names a type: give each column a schema, :schema.table/column (:public.jobs/n)" :pgmalli.error/invalid-config nil]
             (fails {:int4 :int})))
      (is (= [":overrides: :inet names a type: give each column a schema, :schema.table/column; no column of the schemas generated: public has it" :pgmalli.error/invalid-config nil]
             (fails {:inet :string}))))
    (testing "a value is a malli schema"
      (is (= ":overrides: :public.jobs/input's schema [:strin] is no malli schema: invalid-schema {:schema :strin, :form [:strin]}"
             (first (fails {:public.jobs/input [:strin]})))))
    (testing "a column key without its schema, or with pg., names the column meant"
      (is (= [":overrides: :jobs/input names no table or view of the schemas generated: public; did you mean: :public.jobs/input" :pgmalli.error/invalid-config [:public.jobs/input]]
             (fails {:jobs/input :map})))
      (is (= [:public.jobs/input] (last (fails {:pg.public.jobs/input :map})))))
    (let [e (is (thrown-with-msg? clojure.lang.ExceptionInfo
                                  #"^:overrides: :public.jobs/inptu names no column of public.jobs; did you mean: :public.jobs/input$"
                                  (checked {:public.jobs/inptu :map})))]
      (is (= :pgmalli.error/invalid-config (:pgmalli/error (ex-data e))))
      (is (= {:given :public.jobs/inptu :did-you-mean [:public.jobs/input]} (select-keys (ex-data e) [:given :did-you-mean]))))
    (is (thrown-with-msg? clojure.lang.ExceptionInfo #"^:overrides: :public.jobs/nope names no column of public.jobs; it has :public.jobs/input, :public.jobs/n$"
                          (checked {:public.jobs/nope :map})))
    (is (thrown-with-msg? clojure.lang.ExceptionInfo #"^:overrides: :other.jobs/input names no table or view of the schemas generated: public$"
                          (checked {:other.jobs/input :map}))
        "a column of a schema not generated is none")))

(deftest a-file-names-the-servers-major-version-and-16-is-the-oldest
  (is (= ["PostgreSQL 17" "PostgreSQL 17" "PostgreSQL 19" "PostgreSQL 16"]
         (map files/major-version ["PostgreSQL 17.6" "PostgreSQL 17.6 (Debian 17.6-1.pgdg120+1)" "PostgreSQL 19beta1" "PostgreSQL 16devel"])))
  (let [e (is (thrown-with-msg? clojure.lang.ExceptionInfo #"^PostgreSQL 15.4 is older than pgmalli reads: generate from PostgreSQL 16 or later$"
                                (files/major-version "PostgreSQL 15.4")))]
    (is (= :pgmalli.error/fault (:pgmalli/error (ex-data e))))))
